function renderResult(){const r=result;window.dispatchEvent(new Event('stack-lab:result'));for(const seconds of [10,30,60])$('#damage-'+seconds).textContent=fmt(r.damage?.[seconds]??0);renderDefenceNote(r.correction);$('#score').textContent=(r.actual/1e12).toLocaleString('ko-KR',{maximumFractionDigits:2});$('#actual-dps').textContent=fmt(r.actual);$('#theory-dps').textContent=fmt(r.theory);$('#kill-time').textContent=!CoopGemTools.active(state).cells.length?'유닛을 배치해 주세요.':r.seconds!==null?'원본 예상 처치 '+r.seconds.toFixed(2)+'초':'제한 시간 내 처치 실패';$('#contributions').replaceChildren();if(!r.units.length){const p=document.createElement('p');p.className='empty';p.textContent='유닛을 배치하면 진영별 기여도가 표시됩니다.';$('#contributions').append(p);return}const units=[...r.units].sort((a,b)=>b.dps-a.dps),max=Math.max(1,...units.map(u=>u.dps));for(const u of units){const row=document.createElement('div');row.className='contribution';const img=document.createElement('img');img.src='/assets/units/'+D.DEMON_BY_SLUG.get(u.slug).img+'.webp';img.alt='';const box=document.createElement('div');const b=document.createElement('b');b.textContent=name(u.slug);const s=document.createElement('small');s.textContent=(G.sideOf(u.row)==='you'?'내 진영':'파트너')+' '+G.tileName(u.row*7+u.col)+' · '+(u.liberated&&u.stats?.lib>0?'해방 '+u.stats.lib:'미해방')+' · 사거리 적용 '+Math.round((u.cover??0)*100)+'%';const track=document.createElement('div');track.className='track';const fill=document.createElement('i');fill.style.width=(u.dps/max*100)+'%';track.append(fill);box.append(b,s,track);const strong=document.createElement('strong');strong.textContent=fmt(u.dps);row.append(img,box,strong);row.onclick=()=>{selectCell(at(u.row,u.col));openUnitSettings()};$('#contributions').append(row)}}
function renderAccount(){const s=$('#account-side').value,p=state[s],wrap=$('#account-settings');wrap.replaceChildren();for(const[k,l,min,max]of[['enhance','공격력 강화',1,50],['gold','보유 골드',0,1e15],['magicStones','보유 마석',0,1e12],['otherAtk','추가 공격력 %',0,1e6],['otherCritRate','추가 치명타 확률 %',0,1e5],['otherCritDmg','추가 치명타 피해 %',0,1e6],['extraAtkSpd','추가 공격 속도 %',0,1e5],['extraFinal','추가 최종 피해 %',0,1e5],['pressureLv','심해 수압 단계',1,5],['runePotential','잠재력 룬',0,11],['runeSlow','감속 룬',0,11],['legionLevel','군단 레벨',1,30]])inputRow(wrap,l,p[k],min,max,n=>{snapshot();p[k]=n;refresh();queue()});const heading=document.createElement('div');heading.className='section-title';heading.dataset.icon='crown';heading.textContent='공통 유물';wrap.append(heading);for(const[k,label]of[['axe','맹공의 도끼'],['blade','수정 칼날'],['claw','날카로운 발톱'],['core','마신의 핵'],['eye','악마의 눈'],['feather','깃털'],['wind','바람의 축복']])inputRow(wrap,label,p.relics[k]??0,0,32,n=>{snapshot();p.relics={...p.relics,[k]:n};refresh();queue()});const traitLink=document.createElement('button');traitLink.textContent='특성 세팅 열기';traitLink.onclick=()=>openTraits(s);wrap.append(traitLink);$('#account-json').value=JSON.stringify(p,null,2)}

const traitNames={'enemy-def':'모든 적 방어력','atk':'공격력','crit-dmg':'치명타 피해','crit-rate':'치명타 확률','exp':'경험치 보상','silver':'은화 보상','start-gold':'시작 골드','start-stone':'시작 마석','stamina':'최대 행동력','slime-cost':'채광 슬라임 비용','summon-cost':'몬스터 소환 비용','switch-cost':'몬스터 교체 비용','secret-board':'비밀 드로잉 보드'},traitGroups={Combat:'전투',Economy:'보상',Utility:'편의'};
let traitSide='you';
function validTraits(traits){if(!Array.isArray(traits)||traits.length>CoopExtras.TRAIT_SLOTS)throw Error('특성은 최대 5개까지 설정할 수 있습니다.');return traits.filter(t=>t.id!=='').map(t=>{const tr=CoopExtras.TRAIT_BY_ID.get(t.id),range=tr?.ranges[t.rank];if(!range||!Number.isFinite(t.value??range[1])||(t.value??range[1])<range[0]||(t.value??range[1])>range[1])throw Error('특성 종류·등급·수치 범위를 확인하세요.');return{...t,value:t.value??range[1]}})}
function traitText(t){const tr=CoopExtras.TRAIT_BY_ID.get(t.id);return tr?(traitNames[t.id]||tr.name)+' '+t.rank+' '+CoopExtras.formatTraitValue(tr,t.value,t.rank):''}
function renderTraitSummary(){const box=$('#traits-summary');box.replaceChildren();for(const side of state.partnerEnabled?['you','partner']:['you']){const row=document.createElement('div');row.className='traits-summary-row';const label=document.createElement('b');label.textContent=side==='you'?'내 진영':'파트너';const traits=(state[side].traits||[]).filter(t=>t.id);row.append(label);if(!traits.length){const empty=document.createElement('span');empty.textContent='설정된 특성 없음';row.append(empty)}for(const t of traits){const chip=document.createElement('span');chip.className='trait-chip';chip.textContent=traitText(t);row.append(chip)}const button=document.createElement('button');button.textContent='수정 '+traits.length+'/5';button.setAttribute('aria-label',(side==='you'?'내 진영':'파트너')+' 특성 수정');button.onclick=()=>openTraits(side);row.append(button);box.append(row)}}
function openTraits(side='you'){traitSide=state.partnerEnabled?side:'you';renderTraits();openSettings('traits-dialog')}
function saveTraits(next,renderEditor=true){const valid=validTraits(next);if(JSON.stringify(valid)===JSON.stringify(state[traitSide].traits))return;snapshot();state[traitSide].traits=valid;if(renderEditor)renderTraits();renderTraitSummary();renderAccount();queue()}
function renderTraits(){const traits=(state[traitSide].traits||[]).filter(t=>t.id),list=$('#trait-list');list.replaceChildren();for(const btn of document.querySelectorAll('[data-trait-side]'))btn.classList.toggle('on',btn.dataset.traitSide===traitSide);$('#trait-count').textContent=(traitSide==='you'?'내 진영':'파트너')+' · '+traits.length+' / 5';$('#add-trait').disabled=traits.length>=CoopExtras.TRAIT_SLOTS;
for(const [index,t]of traits.entries()){const tr=CoopExtras.TRAIT_BY_ID.get(t.id),row=document.createElement('div');row.className='trait-editor-row';const select=document.createElement('select');select.setAttribute('aria-label','특성 '+(index+1)+' 종류');for(const group of ['Combat','Economy','Utility']){const optgroup=document.createElement('optgroup');optgroup.label=traitGroups[group];for(const item of CoopExtras.TRAITS.filter(x=>x.category===group)){const op=document.createElement('option');op.value=item.id;op.textContent=traitNames[item.id]||item.name;optgroup.append(op)}select.append(optgroup)}select.value=t.id;const rank=document.createElement('select');rank.setAttribute('aria-label','특성 '+(index+1)+' 등급');for(const r of CoopExtras.traitRanks(tr)){const op=document.createElement('option');op.value=r;op.textContent=r;rank.append(op)}rank.value=t.rank;const range=tr.ranges[t.rank],value=document.createElement('input');value.type='number';value.step='1';value.min=range[0];value.max=range[1];value.value=t.value??range[1];value.setAttribute('aria-label','특성 '+(index+1)+' 수치');const amount=document.createElement('label');amount.className='trait-amount';amount.append(document.createTextNode(tr.sign),value,document.createTextNode(tr.unit));const remove=document.createElement('button');remove.textContent='삭제';remove.setAttribute('aria-label','특성 '+(index+1)+' 삭제');const note=document.createElement('small');note.textContent=traitGroups[tr.category]+' · '+tr.sign+range[0]+'–'+range[1]+tr.unit+' · '+tr.name;
const update=(next,renderEditor=true)=>saveTraits((state[traitSide].traits||[]).filter(t=>t.id).map((old,i)=>i===index?{...old,...next}:old),renderEditor);select.onchange=()=>{const item=CoopExtras.TRAIT_BY_ID.get(select.value),r=CoopExtras.traitRanks(item).includes(t.rank)?t.rank:CoopExtras.traitRanks(item)[0];update({id:item.id,rank:r,value:item.ranges[r][1]})};rank.onchange=()=>update({rank:rank.value,value:tr.ranges[rank.value][1]});value.oninput=()=>{if(value.value!==''&&value.checkValidity())update({value:Number(value.value)},false)};value.onchange=()=>{if(value.value===''||!value.checkValidity()){value.reportValidity();return}update({value:Number(value.value)},false)};remove.onclick=()=>saveTraits((state[traitSide].traits||[]).filter(t=>t.id).filter((_,i)=>i!==index));row.append(select,rank,amount,remove,note);list.append(row)}
}
$('#edit-traits').onclick=()=>openTraits(side);$('#close-traits').onclick=()=>$('#traits-dialog').close();for(const button of document.querySelectorAll('[data-trait-side]'))button.onclick=()=>{traitSide=button.dataset.traitSide;renderTraits()};$('#add-trait').onclick=()=>{const traits=(state[traitSide].traits||[]).filter(t=>t.id);if(traits.length>=5)return;const tr=CoopExtras.TRAITS[0],rank=CoopExtras.traitRanks(tr)[0];saveTraits([...traits,{id:tr.id,rank,value:tr.ranges[rank][1]}])};


let gemWorker=null,gemJob=0,gemProposal=null;
function validateInventory(list){if(!Array.isArray(list)||list.length>270)throw Error('보유 보석 목록 형식을 확인하세요.');const seen=new Set;for(const g of list){const data=D.GEM_BY_ID.get(g.id),grades=data?.special?['S','SS','SSS']:D.GRADES,key=CoopGemTools.gemKey(g);if(!data||!grades.includes(g.grade)||!Number.isInteger(g.count)||g.count<1||g.count>999||seen.has(key))throw Error('보유 보석의 종류·등급·개수를 확인하세요.');seen.add(key)}}
function renderPartner(){const enabled=!!state.partnerEnabled;if(!enabled){side='you';if(viewSide!=='you')viewSide='you'}$('#team-title').textContent=enabled?'내 덱 + 파트너 DPS':'내 덱 DPS';$('#toggle-partner').textContent=enabled?'파트너 제외':'＋ 파트너 추가';$('#partner-note').textContent=enabled?'파트너의 배치·특성·보석을 포함해 계산합니다.':'내 진영의 배치와 세팅만 계산합니다.';for(const selector of ['#side-partner','[data-board-view="partner"]','[data-board-view="full"]','[data-trait-side="partner"]']){const el=$(selector);if(el)el.hidden=!enabled}for(const selector of ['#account-side','#preset-side','#gem-side']){const select=$(selector),option=select.querySelector('option[value="partner"]');option.hidden=option.disabled=!enabled;if(!enabled&&select.value==='partner')select.value='you'}}
$('#toggle-partner').onclick=()=>{snapshot();state.partnerEnabled=!state.partnerEnabled;if(state.partnerEnabled){side='partner';viewSide='partner';for(const id of ['#gem-side','#preset-side','#account-side'])$(id).value='partner'}result=null;refresh();queue()};
function gemIcon(gem){const data=D.GEM_BY_ID.get(gem.id),box=document.createElement('span');box.className='owned-gem-icon';box.title=(ko[data?.name]||data?.name||gem.id)+' '+gem.grade;const stone=document.createElement('img');stone.src='/assets/gems/stone-'+gem.grade.toLowerCase()+'.webp';stone.alt='';const glyph=document.createElement('img');glyph.src='/assets/gems/'+gem.id+'.webp';glyph.alt=box.title;box.append(stone,glyph);return box}
function defenceNow(){const target=T.TARGET_BY_ID.get(state.target),forSide=side=>CoopAccount.spawnShredOf({...state[side],mode:state.mode,wave:target?.wave||100}).total;return CoopGemTools.penalty(forSide('you')+(state.partnerEnabled?forSide('partner'):0))}
function renderDefenceNote(correction){const c=correction||defenceNow();$('#defence-overview').textContent='방감 '+c.defence.toFixed(1)+'% · DPS ×'+c.factor.toFixed(3);$('#defence-note').textContent='공통 방어력 감소 '+c.defence.toFixed(1)+'% · 75% 기준 부족 '+c.deficit.toFixed(1)+'%p · 전체 DPS ×'+c.factor.toFixed(3)+(result?.rawActual!==undefined?' · 원본 '+fmt(result.rawActual)+' → 보정 '+fmt(result.actual):'')+' (연구소 추가 표시 보정)'}
function renderGemLab(){const team=$('#gem-side').value,p=state[team],wrap=$('#codex-settings');wrap.replaceChildren();for(const [key,label]of [['codexSS','SS 보석 도감 단계'],['codexSSS','SSS 보석 도감 단계']])inputRow(wrap,label,p[key]??0,0,9,n=>{snapshot();p[key]=n;result=null;refresh();queue()});renderDefenceNote();const list=CoopGemTools.inventoryOf(state,team),used=CoopGemTools.usage(state.cells,p,team),box=$('#inventory-list');box.replaceChildren();for(const g of list){const row=document.createElement('div');row.className='owned-gem-row';row.append(gemIcon(g));const label=document.createElement('span');label.textContent=(ko[D.GEM_BY_ID.get(g.id)?.name]||D.GEM_BY_ID.get(g.id)?.name)+' '+g.grade;const count=document.createElement('input');count.type='number';count.min=1;count.max=999;count.value=g.count;count.setAttribute('aria-label',label.textContent+' 보유 개수');count.oninput=()=>{if(!count.checkValidity()||count.value==='')return;snapshot();g.count=+count.value;g.manual=true;renderStockNote();persistState();cancelGemRecommendation()};const note=document.createElement('small');const renderStockNote=()=>{const n=used.get(CoopGemTools.gemKey(g))||0;note.textContent='배치 장착 '+n+(n>g.count?' · 보유 부족':'');note.classList.toggle('stock-short',n>g.count)};renderStockNote();const remove=document.createElement('button');remove.textContent='삭제';remove.setAttribute('aria-label',label.textContent+' 보유 삭제');remove.onclick=()=>{snapshot();state.inventory[team]=list.filter(x=>x!==g);refresh();queue()};row.append(label,count,note,remove);box.append(row)}if(!list.length)box.textContent='등록된 보유 보석이 없습니다. 위에서 종류·등급·개수를 추가하세요.';const unlock=state.cells.some(c=>G.sideOf(c.row)===team&&E.effectiveLib(p,c.slug)>=3);$('#recommend-gems').disabled=!!gemWorker||!unlock||!list.length;if(!gemWorker&&!gemProposal)$('#gem-search-status').textContent=!unlock?'추천할 진영에 해방 3단계 이상의 유닛을 배치하세요.':!list.length?'보유 보석 목록을 먼저 작성하세요.':'보유 개수 안에서 추천 · 각성은 아이비에만 추천합니다.'}
function stockGrades(){const data=D.GEM_BY_ID.get($('#stock-gem').value),select=$('#stock-grade');select.replaceChildren();for(const grade of data?.special?['S','SS','SSS']:D.GRADES){const option=document.createElement('option');option.value=option.textContent=grade;select.append(option)}select.value='SSS'}
for(const gem of D.GEMS){const option=document.createElement('option');option.value=gem.id;option.textContent=ko[gem.name]||gem.name;$('#stock-gem').append(option)}
$('#stock-gem').onchange=stockGrades;stockGrades();$('#gem-side').onchange=()=>{cancelGemRecommendation();renderGemLab()};
$('#add-stock').onclick=()=>{const count=Number($('#stock-count').value);if(!Number.isInteger(count)||count<1||count>999){$('#stock-count').reportValidity();return}const team=$('#gem-side').value,list=CoopGemTools.inventoryOf(state,team),id=$('#stock-gem').value,grade=$('#stock-grade').value,old=list.find(g=>g.id===id&&g.grade===grade);if(old&&old.count+count>999){$('#gem-search-status').textContent='같은 보석은 최대 999개까지 등록할 수 있습니다.';return}snapshot();if(old){old.count+=count;old.manual=true}else list.push({id,grade,count,manual:true});refresh();queue()};
$('#collect-stock').onclick=()=>{snapshot();CoopGemTools.collectEquipped(state,$('#gem-side').value,true);refresh();queue()};
function cancelGemRecommendation(){if(gemWorker){gemWorker.terminate();gemWorker=null}gemProposal=null;$('#gem-preview').hidden=true;$('#cancel-gems').hidden=true;const team=$('#gem-side').value;$('#recommend-gems').disabled=!CoopGemTools.inventoryOf(state,team).length||!state.cells.some(c=>G.sideOf(c.row)===team&&E.effectiveLib(state[team],c.slug)>=3)}
function startGemRecommendation(){cancelGemRecommendation();const team=$('#gem-side').value;if(!state.partnerEnabled&&team==='partner')return;const list=CoopGemTools.inventoryOf(state,team);if(!list.length||!state.cells.some(c=>G.sideOf(c.row)===team&&E.effectiveLib(state[team],c.slug)>=3))return;const id=++gemJob;gemWorker=new Worker(workerUrl);$('#recommend-gems').disabled=true;$('#cancel-gems').hidden=false;$('#gem-search-status').textContent='보유 보석으로 현재 배치 DPS 계산 중…';gemWorker.onmessage=({data})=>{if(data.id!==id)return;if(data.error){cancelGemRecommendation();$('#gem-search-status').textContent='추천 실패: '+data.error;return}if(data.kind==='gem-progress'){$('#gem-search-status').textContent=data.evaluated+'개 조합 검토 · 최고 DPS '+fmt(data.best);return}if(data.kind==='recommended'){gemWorker.terminate();gemWorker=null;$('#cancel-gems').hidden=true;$('#recommend-gems').disabled=false;gemProposal=data;showGemProposal()}};gemWorker.onerror=e=>{cancelGemRecommendation();$('#gem-search-status').textContent='추천 오류: '+e.message};gemWorker.postMessage({kind:'recommend',id,cells:state.cells,marks:state.marks||[],partnerEnabled:!!state.partnerEnabled,you:state.you,partner:state.partner,mode:state.mode,target:state.target,recommendSide:team,inventory:list})}
function showGemProposal(){const proposal=gemProposal,box=$('#gem-preview');box.hidden=false;box.replaceChildren();const headline=document.createElement('p');headline.textContent='현재 DPS '+fmt(proposal.baseline)+' → 추천 '+fmt(proposal.result.actual)+' · '+proposal.evaluated+'개 조합 검토 · 각성은 아이비에만 추천'+(proposal.originalPolicyValid===false?' · 기존 각성 배정을 추천 기준에 맞게 변경했습니다.':'')+(!proposal.originalValid?' · 기존 세팅이 보유 수량/슬롯 제한을 초과해 보유 범위로 조정했습니다.':'');box.append(headline);const slugs=[...new Set(state.cells.filter(c=>G.sideOf(c.row)===proposal.side).map(c=>c.slug))];for(const slug of slugs){const row=document.createElement('div');row.className='gem-proposal-row';const label=document.createElement('b');label.textContent=name(slug);row.append(label);for(const gem of proposal.build[slug]?.gems||[]){if(!gem.id)continue;const chip=document.createElement('span');chip.append(gemIcon(gem),document.createTextNode((ko[D.GEM_BY_ID.get(gem.id)?.name]||gem.id)+' '+gem.grade));row.append(chip)}box.append(row)}const apply=document.createElement('button');apply.textContent='추천 보석 적용';apply.onclick=()=>{const p=gemProposal;if(!p)return;snapshot();state[p.side].perDemon=p.build;gemProposal=null;refresh();queue();$('#gem-search-status').textContent='✓ 추천 보석을 적용했습니다. 되돌리기로 복원할 수 있습니다.'};const cancel=document.createElement('button');cancel.textContent='닫기';cancel.onclick=cancelGemRecommendation;box.append(apply,cancel);$('#gem-search-status').textContent='추천 완료 · 적용 전에 조합을 확인하세요.'}
$('#recommend-gems').onclick=startGemRecommendation;$('#cancel-gems').onclick=()=>{cancelGemRecommendation();renderGemLab();$('#gem-search-status').textContent='탐색을 중지했습니다. 기존 세팅은 유지됩니다.'};


function openSettings(id){for(const dialog of document.querySelectorAll('.settings-dialog[open]'))if(dialog.id!==id)dialog.close();const dialog=document.getElementById(id);if(!dialog.open)dialog.showModal()}
function openUnitSettings(fromLibrary=false){$('#unit-library-back').hidden=fromLibrary!==true;renderInspector();openSettings('unit-dialog')}
function openUnitLibrary(){renderUnitLibrary();openSettings('unit-library-dialog')}
