function checkParams(p){if(!p||typeof p!=='object'||Array.isArray(p)||!p.perDemon||typeof p.perDemon!=='object')throw Error('perDemon을 포함한 파라미터 객체가 필요합니다.');for(const k of Object.keys(E.DEFAULT_PARAMS))if(!(k in p))throw Error('필수 파라미터 누락: '+k);validTraits(p.traits);return p}
